/**
 * Journey Booking — Authorize Payment Request DTO
 *
 * Represents the HTTP request body used to authorize a payment.
 *
 * The booking public ID comes from the route parameter.
 * The correlation ID is generated by the controller.
 * The transaction public ID identifies the existing payment transaction.
 * The authorization timestamp is optional; when omitted, the application
 * uses the current time.
 */

import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import {
  IsDateString,
  IsString,
  MaxLength,
  MinLength,
  IsOptional,
} from 'class-validator';

export class AuthorizeJourneyBookingPaymentDto {
  @ApiProperty({
    description:
      'Public identifier of the transaction associated with the Journey Booking payment.',
    example: 'TXN-8K3P2Q1A',
    minLength: 1,
    maxLength: 100,
  })
  @IsString()
  @MinLength(1)
  @MaxLength(100)
  transactionPublicId!: string;

  @ApiPropertyOptional({
    description:
      'Explicit payment authorization timestamp. When omitted, the application uses the current time.',
    example: '2026-08-18T17:00:00.000Z',
    format: 'date-time',
  })
  @IsOptional()
  @IsDateString()
  authorizedAt?: string;
}

export default AuthorizeJourneyBookingPaymentDto;
